-- Apply to a NEW Supabase project. All client access is authenticated and policy checked.
create extension if not exists pgcrypto with schema extensions;
create table public.universes(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 100),owner_id uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.universe_members(universe_id uuid references public.universes on delete cascade,user_id uuid references auth.users on delete cascade,joined_at timestamptz not null default now(),primary key(universe_id,user_id));
create table public.universe_invites(id uuid primary key default gen_random_uuid(),universe_id uuid not null references public.universes on delete cascade,token_hash text unique not null,expires_at timestamptz not null default now()+interval '7 days',used_at timestamptz,revoked boolean not null default false);
create table public.cloud_records(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users,universe_id uuid references public.universes on delete cascade,kind text not null check(kind in ('memory','reflection','constellation','chapter','snapshot','ritual')),source_id text,payload jsonb not null check(jsonb_typeof(payload)='object'),created_at timestamptz not null default now(),unique(owner_id,universe_id,kind,source_id));
create unique index personal_record_source on public.cloud_records(owner_id,kind,source_id) where universe_id is null;
create table public.capsules(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users,title text not null check(length(title) between 1 and 100),unlock_at timestamptz not null,sealed boolean not null default false,created_at timestamptz not null default now());
create table public.capsule_bodies(capsule_id uuid primary key references public.capsules on delete cascade,body text not null default '',audio_path text);
create table public.capsule_replies(id uuid primary key default gen_random_uuid(),capsule_id uuid not null references public.capsules on delete cascade,owner_id uuid not null default auth.uid() references auth.users,body text not null default '',audio_path text,created_at timestamptz not null default now(),check(length(body)>0 or audio_path is not null));
create function public.is_member(g uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from universe_members where universe_id=g and user_id=auth.uid())$$;
create function public.is_owner(g uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from universes where id=g and owner_id=auth.uid())$$;
create function public.can_read_record(r uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from cloud_records where id=r and ((universe_id is null and owner_id=auth.uid()) or is_member(universe_id)))$$;
create function public.capsule_open(c uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from capsules where id=c and owner_id=auth.uid() and sealed and unlock_at<=now())$$;
alter table public.universes enable row level security;
alter table public.universe_members enable row level security;
alter table public.universe_invites enable row level security;
alter table public.cloud_records enable row level security;
alter table public.capsules enable row level security;
alter table public.capsule_bodies enable row level security;
alter table public.capsule_replies enable row level security;
create policy group_read on public.universes for select to authenticated using(is_member(id));
create policy members_read on public.universe_members for select to authenticated using(is_member(universe_id));
create policy members_remove on public.universe_members for delete to authenticated using((is_owner(universe_id) or user_id=auth.uid()) and not exists(select 1 from universes where id=universe_id and owner_id=universe_members.user_id));
create policy invites_read on public.universe_invites for select to authenticated using(is_owner(universe_id));
create policy records_read on public.cloud_records for select to authenticated using((universe_id is null and owner_id=auth.uid()) or is_member(universe_id));
create policy records_insert on public.cloud_records for insert to authenticated with check(owner_id=auth.uid() and (universe_id is null or is_member(universe_id)));
create policy records_update on public.cloud_records for update to authenticated using(owner_id=auth.uid() and (universe_id is null or is_member(universe_id))) with check(owner_id=auth.uid() and (universe_id is null or is_member(universe_id)));
create policy records_delete on public.cloud_records for delete to authenticated using((owner_id=auth.uid() and (universe_id is null or is_member(universe_id))) or is_owner(universe_id));
create function public.immutable_record_scope() returns trigger language plpgsql set search_path=public as $$begin if new.owner_id<>old.owner_id or new.universe_id is distinct from old.universe_id or new.kind<>old.kind then raise exception 'Record ownership and scope cannot change';end if;return new;end$$;
create trigger record_scope before update on public.cloud_records for each row execute function public.immutable_record_scope();
create policy capsule_metadata_read on public.capsules for select to authenticated using(owner_id=auth.uid());
create policy capsule_delete on public.capsules for delete to authenticated using(owner_id=auth.uid());
create policy capsule_body_read on public.capsule_bodies for select to authenticated using(capsule_open(capsule_id));
create policy replies_read on public.capsule_replies for select to authenticated using(capsule_open(capsule_id));
create policy replies_insert on public.capsule_replies for insert to authenticated with check(owner_id=auth.uid() and capsule_open(capsule_id) and (audio_path is null or audio_path like auth.uid()::text||'/capsules/'||capsule_id::text||'/%'));

create function public.create_universe(group_name text) returns uuid language plpgsql security definer set search_path=public as $$declare g uuid;begin if auth.uid() is null then raise exception 'Sign in first';end if;insert into universes(name,owner_id) values(trim(group_name),auth.uid()) returning id into g;insert into universe_members values(g,auth.uid(),now());return g;end$$;
create function public.create_invite(group_id uuid) returns text language plpgsql security definer set search_path=public,extensions as $$declare token text;begin if not is_owner(group_id) then raise exception 'Only the owner can invite';end if;token:=encode(extensions.gen_random_bytes(32),'hex');insert into universe_invites(universe_id,token_hash) values(group_id,encode(extensions.digest(token,'sha256'),'hex'));return token;end$$;
create function public.revoke_invite(invite_id uuid) returns void language plpgsql security definer set search_path=public as $$begin update universe_invites set revoked=true where id=invite_id and is_owner(universe_id);if not found then raise exception 'Invite not found or not owned';end if;end$$;
create function public.accept_invite(token text) returns uuid language plpgsql security definer set search_path=public,extensions as $$declare invite universe_invites;begin if auth.uid() is null then raise exception 'Sign in first';end if;select * into invite from universe_invites where token_hash=encode(extensions.digest(token,'sha256'),'hex') for update;if invite.id is null or invite.revoked or invite.used_at is not null or invite.expires_at<=now() then raise exception 'This invitation is invalid, expired, or already used';end if;insert into universe_members(universe_id,user_id) values(invite.universe_id,auth.uid()) on conflict do nothing;update universe_invites set used_at=now() where id=invite.id;return invite.universe_id;end$$;
create function public.create_capsule(capsule_title text,release_at timestamptz) returns uuid language plpgsql security definer set search_path=public as $$declare c uuid;begin if auth.uid() is null then raise exception 'Sign in first';end if;if release_at<=now() then raise exception 'Choose a future release time';end if;insert into capsules(title,unlock_at,owner_id) values(trim(capsule_title),release_at,auth.uid()) returning id into c;return c;end$$;
create function public.seal_capsule(capsule_id uuid,message text,voice_path text default null) returns void language plpgsql security definer set search_path=public as $$declare c capsules;begin select * into c from capsules where id=capsule_id and owner_id=auth.uid() for update;if c.id is null or c.sealed or c.unlock_at<=now() then raise exception 'Capsule is unavailable or already sealed';end if;if length(trim(message))=0 and voice_path is null then raise exception 'Add text or voice';end if;if voice_path is not null and voice_path not like auth.uid()::text||'/capsules/'||c.id::text||'/%' then raise exception 'Invalid media path';end if;insert into capsule_bodies values(c.id,message,voice_path);update capsules set sealed=true where id=c.id;end$$;
create function public.capsule_status() returns table(id uuid,title text,unlock_at timestamptz,sealed boolean,available boolean) language sql stable security definer set search_path=public as $$select id,title,unlock_at,sealed,(sealed and unlock_at<=now()) from capsules where owner_id=auth.uid() order by unlock_at$$;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('echoverse-private','echoverse-private',false,20971520,array['image/jpeg','image/png','image/webp','audio/mp4','audio/m4a','audio/x-m4a','audio/webm','audio/ogg','audio/wav','application/octet-stream']);
-- Paths: user/records/record-id/file or user/capsules/capsule-id/file.
create function public.can_read_media(path text) returns boolean language plpgsql stable security definer set search_path=public as $$declare parts text[]:=string_to_array(path,'/');r uuid;begin r:=parts[3]::uuid;if parts[2]='records' then return can_read_record(r);elsif parts[2]='capsules' then return capsule_open(r);end if;return false;exception when invalid_text_representation then return false;end$$;
create function public.can_write_media(path text) returns boolean language plpgsql stable security definer set search_path=public as $$declare parts text[]:=string_to_array(path,'/');r uuid;begin if parts[1]<>auth.uid()::text then return false;end if;r:=parts[3]::uuid;if parts[2]='records' then return exists(select 1 from cloud_records where id=r and owner_id=auth.uid() and (universe_id is null or is_member(universe_id)));elsif parts[2]='capsules' then return exists(select 1 from capsules where id=r and owner_id=auth.uid() and (not sealed or unlock_at<=now()));end if;return false;exception when invalid_text_representation then return false;end$$;
create policy media_read on storage.objects for select to authenticated using(bucket_id='echoverse-private' and can_read_media(name));
create policy media_insert on storage.objects for insert to authenticated with check(bucket_id='echoverse-private' and can_write_media(name));
create policy media_delete on storage.objects for delete to authenticated using(bucket_id='echoverse-private' and (storage.foldername(name))[1]=auth.uid()::text);
-- Remove broad default privileges; only the operations with policies/RPCs are available.
revoke all on public.universes,public.universe_members,public.universe_invites,public.cloud_records,public.capsules,public.capsule_bodies,public.capsule_replies from anon,authenticated;
grant select on public.universes,public.universe_members,public.capsules,public.capsule_bodies,public.capsule_replies to authenticated;
grant select(id,universe_id,expires_at,used_at,revoked) on public.universe_invites to authenticated;
grant select,insert,update,delete on public.cloud_records to authenticated;
grant delete on public.universe_members,public.capsules to authenticated;
grant insert on public.capsule_replies to authenticated;
revoke execute on function public.is_member(uuid),public.is_owner(uuid),public.can_read_record(uuid),public.capsule_open(uuid),public.create_universe(text),public.create_invite(uuid),public.revoke_invite(uuid),public.accept_invite(text),public.create_capsule(text,timestamptz),public.seal_capsule(uuid,text,text),public.capsule_status(),public.can_read_media(text),public.can_write_media(text) from public,anon;
grant execute on function public.is_member(uuid),public.is_owner(uuid),public.can_read_record(uuid),public.capsule_open(uuid),public.create_universe(text),public.create_invite(uuid),public.revoke_invite(uuid),public.accept_invite(text),public.create_capsule(text,timestamptz),public.seal_capsule(uuid,text,text),public.capsule_status(),public.can_read_media(text),public.can_write_media(text) to authenticated;
create index member_user on public.universe_members(user_id);
create index record_universe on public.cloud_records(universe_id);
create index capsule_owner on public.capsules(owner_id);
